import {compile,primitive,invert} from './engine.js';
const id=s=>'n_'+String(s).replace(/[^a-zA-Z0-9_]+/g,'_').replace(/_+/g,'_').replace(/^_|_$/g,'');
const gateType=t=>/^(AND|NAND|OR|NOR|XOR|XNOR)(\d+)?(B\d+)?$/.test(t)||/^(INV|NOT|IV|BUF|IBUF|OBUF|BUFG|IDENTITY|VCC|GND|PULLUP|PULLDOWN)$/.test(t)||/^MUX[248]$|^M[248]_1$/.test(t);
export function flattenCircuit(circuit,data){
 const ports=[],gates=[],nets=new Set(),assignments=[];let serial=0;
 function walk(c,prefix,bindings={},depth=0){if(depth>24)throw Error('계층 회로가 순환하거나 너무 깊습니다.');const g=compile(c,data),mapping=new Map(),get=n=>{if(!mapping.has(n)){mapping.set(n,'w'+serial++);nets.add(mapping.get(n));}return mapping.get(n);};
 for(const part of c.components.filter(p=>p.kind!=='GATE')){const local=get(g.root([part.x,part.y]));if(prefix==='top'){const name=id(part.name);ports.push({name,original:part.name,direction:part.kind});assignments.push(part.kind==='INPUT'?[local,name]:[name,local]);}else if(bindings[part.name])assignments.push(part.kind==='INPUT'?[local,bindings[part.name]]:[bindings[part.name],local]);}
 for(const part of c.components.filter(p=>p.kind==='GATE')){const pins=g.pins.filter(p=>p.component===part.id),inputs={},outputs={},type=part.symbol.split('/').at(-1);for(const p of pins){const net=get(p.net);if(p.direction===1){let inverse=(part.portBubbles||[]).includes(p.name)!==(!!p.bubble&&part.symbol.startsWith('PRIMITIVE/'));inputs[p.name]={net,inverse};}else outputs[p.name]={net,inverse:(part.portBubbles||[]).includes(p.name)};}
 if(!Object.keys(outputs).length){if(!pins.length)throw Error('HDL 모델 미지원: '+type);continue;}
 if(gateType(type)||/^FD(C|P|R|S|E|CE|PE|RE|SE)?$|^DFF$|^REG(CKE|RS)?$/.test(type))gates.push({name:id(prefix+'_'+part.id),type,inputs,outputs});else{const sub=data.circuits[type]||data.models?.[part.symbol];if(!sub)throw Error('HDL 모델 미지원: '+type);const map={};for(const [name,p]of Object.entries({...inputs,...outputs})){if(p.inverse){const inverted='w'+serial++;nets.add(inverted);assignments.push(name in inputs?[inverted,{net:p.net,inverse:true}]:[p.net,{net:inverted,inverse:true}]);map[name]=inverted;}else map[name]=p.net;}walk(sub,prefix+'_'+part.id,map,depth+1);}}
 }walk(circuit,'top');if(ports.length!==new Set(ports.map(p=>p.name)).size)throw Error('포트 이름이 중복되거나 HDL 식별자로 변환할 수 없습니다.');return {name:id(circuit.name),ports,gates,nets:[...nets],assignments};
}
function expression(g,language){const v=p=>p.inverse?(language==='vhdl'?'not '+p.net:'~'+p.net):p.net,all=Object.entries(g.inputs),b=Number(g.type.match(/B(\d+)/)?.[1]||0),args=all.map(([n,p])=>{const neg=/^I\d+$/.test(n)&&+n.slice(1)<b;return v({...p,inverse:p.inverse!==neg});});const base=g.type.replace(/\d.*$/,'');let e;
 if(['AND','NAND','OR','NOR','XOR','XNOR'].includes(base)){const op=base.includes('AND')?'and':base.includes('XOR')?'xor':'or';e='('+args.join(language==='vhdl'?` ${op} `:` ${{and:'&',or:'|',xor:'^'}[op]} `)+')';if(['NAND','NOR','XNOR'].includes(base))e=(language==='vhdl'?'not ':'~')+e;}
 else if(/^(VCC|PULLUP)$/.test(g.type))e=language==='vhdl'?"'1'":"1'b1";
 else if(/^(GND|PULLDOWN)$/.test(g.type))e=language==='vhdl'?"'0'":"1'b0";
 else if(/^(INV|NOT|IV)$/.test(g.type))e=(language==='vhdl'?'not ':'~')+args[0];
 else if(/^BUF|^[IO]BUF|^IDENTITY/.test(g.type))e=args[0];
 else if(/^MUX[248]$|^M[248]_1$/.test(g.type)){const ss=all.filter(([n])=>/^S\d*$/.test(n)).sort(),width=ss.length,ds=Array.from({length:2**width},(_,i)=>g.inputs['I'+i]||g.inputs['D'+i]||g.inputs['IN'+(i+1)]);if(ds.some(p=>!p))throw Error('MUX 데이터 핀이 없습니다.');e=v(ds.at(-1));for(let i=ds.length-2;i>=0;i--){const condition=ss.map(([,p],j)=>language==='vhdl'?`${v(p)} = '${(i>>j)&1}'`:`${v(p)} == 1'b${(i>>j)&1}`).join(language==='vhdl'?' and ':' && ');e=language==='vhdl'?`${v(ds[i])} when ${condition} else ${e}`:`(${condition} ? ${v(ds[i])} : ${e})`;}}
 else return null;return e;
}
export function exportVerilog(circuit,data){const m=flattenCircuit(circuit,data),lines=[`// Generated by Logic Forge. Scalar structural netlist.`,`module ${m.name}(${m.ports.map(p=>p.name).join(', ')});`,...m.ports.map(p=>`${p.direction==='INPUT'?'input':'output'} wire ${p.name};`),...m.nets.map(n=>'wire '+n+';')];const ref=p=>p.inverse?'~'+p.net:p.net;for(const [a,b]of m.assignments)lines.push(`assign ${a} = ${typeof b==='string'?b:ref(b)};`);
 for(const g of m.gates){const e=expression(g,'verilog');if(e!==null){for(const p of Object.values(g.outputs))lines.push(`assign ${p.net} = ${p.inverse?'~('+e+')':e};`);continue;}const q='q_'+g.name,ins=g.inputs,clk=ins.C||ins.CK||ins.CLK,d=ins.D;if(!clk||!d)throw Error('D/클록 핀이 없는 순차 소자: '+g.type);if(clk.inverse)throw Error('반전 클록에 별도 인버터를 배치하세요.');const ar=ins.CLR,as=ins.PRE,reset=ar||ins.R,set=as||ins.S,enable=ins.CE||ins.EN;lines.push(`reg ${q} = 1'b0;`,`always @(posedge ${ref(clk)}${ar?' or posedge '+ref(ar):''}${as?' or posedge '+ref(as):''}) begin`);if(reset)lines.push(`  if (${ref(reset)}) ${q} <= 1'b0;`);if(set)lines.push(`  ${reset?'else ':''}if (${ref(set)}) ${q} <= 1'b1;`);lines.push(`  ${reset||set?'else ':''}${enable?'if ('+ref(enable)+') ':''}${q} <= ${ref(d)};`,'end');for(const [n,p]of Object.entries(g.outputs))lines.push(`assign ${p.net} = ${p.inverse!== (n==='QB')?'~':''}${q};`);}lines.push('endmodule');return lines.join('\n')+'\n';}
export function exportVHDL(circuit,data){
 const m=flattenCircuit(circuit,data),sequential=m.gates.filter(g=>expression(g,'vhdl')===null);
 const lines=['library ieee;','use ieee.std_logic_1164.all;',`entity ${m.name} is`,m.ports.length?`  port (${m.ports.map(p=>`${p.name}: ${p.direction==='INPUT'?'in':'out'} std_logic`).join('; ')});`:'',`end ${m.name};`,`architecture structural of ${m.name} is`,...m.nets.map(n=>`  signal ${n}: std_logic;`),...sequential.map(g=>`  signal q_${g.name}: std_logic := '0';`),'begin'];
 const ref=p=>p.inverse?'(not '+p.net+')':p.net;
 for(const [a,b]of m.assignments)lines.push(`  ${a} <= ${typeof b==='string'?b:ref(b)};`);
 for(const g of m.gates){const e=expression(g,'vhdl');if(e!==null){for(const p of Object.values(g.outputs)){if(p.inverse&&e.includes(' when '))throw Error('VHDL: MUX 출력에 별도 인버터를 배치하세요.');lines.push(`  ${p.net} <= ${p.inverse?'not ('+e+')':e};`);}continue;}
  const q='q_'+g.name,ins=g.inputs,clk=ins.C||ins.CK||ins.CLK,d=ins.D;if(!clk||!d)throw Error('D/클록 핀이 없는 순차 소자: '+g.type);if(clk.inverse)throw Error('반전 클록에 별도 인버터를 배치하세요.');
  const ar=ins.CLR,as=ins.PRE,en=ins.CE||ins.EN;
  lines.push(`  ${g.name}: process(${[clk.net,ar?.net,as?.net].filter(Boolean).join(', ')}) begin`);
  if(ar)lines.push(`    if ${ref(ar)} = '1' then ${q} <= '0';`);
  if(as)lines.push(`    ${ar?'els':''}if ${ref(as)} = '1' then ${q} <= '1';`);
  lines.push(`    ${ar||as?'els':''}if rising_edge(${clk.net}) then`);
  if(ins.R)lines.push(`      if ${ref(ins.R)} = '1' then ${q} <= '0';`);
  if(ins.S)lines.push(`      ${ins.R?'els':''}if ${ref(ins.S)} = '1' then ${q} <= '1';`);
  if(en)lines.push(`      ${ins.R||ins.S?'els':''}if ${ref(en)} = '1' then ${q} <= ${ref(d)};`);
  else lines.push(`      ${ins.R||ins.S?'else ':''}${q} <= ${ref(d)};`);
  if(en||ins.R||ins.S)lines.push('      end if;');
  lines.push('    end if;','  end process;');
  for(const [name,p]of Object.entries(g.outputs))lines.push(`  ${p.net} <= ${p.inverse!==(name==='QB')?'not ':''}${q};`);
 }
 lines.push('end structural;');return lines.filter(Boolean).join('\n')+'\n';
}
export function exportEDIF(circuit,data){const m=flattenCircuit(circuit,data),cellTypes=new Map();for(const g of m.gates){if(Object.values({...g.inputs,...g.outputs}).some(p=>p.inverse))throw Error('EDIF: 반전 핀은 별도 인버터로 배치한 후 내보내세요.');const key=id(g.type);if(!cellTypes.has(key))cellTypes.set(key,g);}
 const lib=[...cellTypes].map(([key,g])=>`(cell ${key} (cellType GENERIC) (view netlist (viewType NETLIST) (interface ${[...Object.keys(g.inputs).map(n=>`(port ${id(n)} (direction INPUT))`),...Object.keys(g.outputs).map(n=>`(port ${id(n)} (direction OUTPUT))`)].join(' ')})))`).join('\n');const links=new Map(),add=(net,p)=>{if(!links.has(net))links.set(net,[]);links.get(net).push(p);};
 const aliases=new Map(),root=n=>{if(!aliases.has(n))aliases.set(n,n);if(aliases.get(n)!==n)aliases.set(n,root(aliases.get(n)));return aliases.get(n);};for(const [a,b]of m.assignments){if(typeof b!=='string')throw Error('EDIF의 반전 별칭을 지원하지 않습니다.');aliases.set(root(a),root(b));}for(const p of m.ports)add(root(p.name),`(portRef ${p.name})`);for(const g of m.gates)for(const [n,p]of Object.entries({...g.inputs,...g.outputs}))add(root(p.net),`(portRef ${id(n)} (instanceRef ${g.name}))`);
 return `(edif ${m.name} (edifVersion 2 0 0) (edifLevel 0) (keywordMap (keywordLevel 0)) (library LogicForge (edifLevel 0) (technology (numberDefinition)) ${lib} (cell ${m.name} (cellType GENERIC) (view netlist (viewType NETLIST) (interface ${m.ports.map(p=>`(port ${p.name} (direction ${p.direction==='INPUT'?'INPUT':'OUTPUT'}))`).join(' ')}) (contents ${m.gates.map(g=>`(instance ${g.name} (viewRef netlist (cellRef ${id(g.type)} (libraryRef LogicForge))))`).join(' ')} ${[...links].map(([n,ps])=>`(net ${n} (joined ${ps.join(' ')}))`).join(' ')})))) (design ${m.name} (cellRef ${m.name} (libraryRef LogicForge))))\n`;}
